// Combines supabase/migrations/*.sql into one file to paste into the Supabase SQL Editor.
// Usage: npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const out = "supabase/phase1.sql";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const header = `-- VFDA VA Quiz App - Phase 1 database (tables + row-level security).
-- GENERATED by \`npm run db:bundle\` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run once on an empty project.
-- Runs in one transaction: if anything fails, nothing is created.

begin;
`;

const body = files
  .map((f) => `\n-- ===== ${f} =====\n\n${readFileSync(join(dir, f), "utf8").trim()}\n`)
  .join("");

writeFileSync(out, `${header}${body}\ncommit;\n`);
console.log(`Wrote ${out} from ${files.length} migrations: ${files.join(", ")}`);
